('player-match-fee-warning-email', 'player-match-fee-warning-email', 'Individual player payment warning email', 'Admin-confirmed warning for one unpaid player fee, with chosen deadline. No automatic fine or suspension.', 'TRANSACTIONAL', 'EMAIL', 'PLAYER', 'Payment warning: {{amount}} outstanding for {{teamName}}', E'Hi {{firstName}},\n\nOur records show that your {{amount}} match fee for {{fixtureLabel}} is still unpaid.\n\nPlease make payment by {{deadline}} using your secure payment link:\n{{paymentUrl}}\n\n{{cta}}\n\nIf you have already paid or need help, please reply so we can check this with you.\n\nThanks,\nSIXFL', 'Pay this match fee', 'paymentUrl', true, NOW(), NOW()),
('player-match-fee-warning-sms', 'player-match-fee-warning-sms', 'Individual player payment warning SMS', 'Admin-confirmed warning for one unpaid player fee, with chosen deadline. No automatic fine or suspension.', 'TRANSACTIONAL', 'SMS', 'PLAYER', NULL, 'Hi {{firstName}}, payment warning: {{amount}} remains unpaid for {{teamName}} ({{fixtureLabel}}). Please pay by {{deadline}}: {{paymentUrl}}. Already paid or need help? Please reply.', NULL, NULL, true, NOW(), NOW())
