CREATE UNIQUE INDEX IF NOT EXISTS "player_warning_confirmation_request_key" ON "NotificationDispatch" (("metadata"->>'warningRequestId')) WHERE "sourceType" = 'PLAYER_MATCH_FEE_WARNING';
